// Independent auditor PLAY-04 rules-parity probe (Bun, development-only).
// A: compiled project bridge (timed) vs raw unchanged upstream MatchRuntime (timed) on identical commands.
// B: compiled bridge timed vs compiled bridge untimed: game rules/state identical apart from ctx.time.
// C: exact native dynamic arithmetic at the zero boundary, opening/choice behaviour and clock controls.
import assert from 'node:assert/strict';
import { randomBytes } from 'node:crypto';
const ROOT = '/workspaces/lorcana-online-tcg/';
const U = ROOT + 'vendor/tcg-engines/upstream/submodules/lorcana/packages/lorcana/lorcana-engine/src/';
const { createSyntheticKernel, KERNEL_IDENTITY } = await import(ROOT + 'vendor/tcg-engines/dist/kernel.js');
const { createRandomSource } = await import(ROOT + 'packages/engine-adapter/dist/random.js');
const { MatchRuntime } = await import(U + 'core/runtime/match-runtime.ts');
const { lorcanaRuntimeConfig } = await import(U + 'runtime-game/definition.ts');
const { createRecordCardCatalog } = await import(U + 'core/runtime/static-resources.ts');
const { createPlayerId } = await import(U + 'core/types/branded-utils.ts');

const NATIVE = { initialReserveMs: 150000, reserveCapMs: 150000, perActionBonusMs: 5000, perTurnPassBonusMs: 60000, resetTimeOnSkipMs: 60000, graceMs: 0 as const };
const players: [string, string] = ['p1', 'p2'];
const other = (p: string) => (p === 'p1' ? 'p2' : 'p1');
const clone = (v: unknown) => JSON.parse(JSON.stringify(v));

// Raw replica of the bridge's construction (same definitions, identities, config and injected sources),
// but commands go straight to runtime.processCommand with no project pre-validation/pause/restore logic.
function rawRuntime(seed: Buffer, context: string, start: number, clock?: typeof NATIVE) {
  const source = createRandomSource(seed, context);
  let now = start;
  const identity = (domain: string, index: number) => domain + '-' + source.identifier(domain, index);
  const definitions = Object.fromEntries(players.map((_, index) => {
    const id = 'synthetic-' + index;
    return [id, { id, canonicalId: 'ci_' + id, slug: id, printings: [], cardType: 'character', name: 'Synthetic character ' + index, cost: 1, inkType: ['amber'], inkable: true, strength: 1, willpower: 2, lore: 1, classifications: ['Storyborn'], set: 'TST', rarity: 'common', abilities: [], i18n: { en: { name: 'Synthetic character ' + index } }, cardNumber: index + 1 }];
  }));
  const owners = Object.fromEntries(players.map((id, pi) => [id, Array.from({ length: 12 }, (_, i) => identity('instance', pi * 12 + i))]));
  const cardInstances = Object.fromEntries(players.flatMap((id, i) => owners[id].map((inst: string) => [inst, 'synthetic-' + i])));
  const runtime = new MatchRuntime({ ...lorcanaRuntimeConfig, ...(clock ? { timeControl: { mode: 'dynamic', config: { ...clock } } } : {}), randomSource: source, now: () => now, rulesetIdentity: KERNEL_IDENTITY } as never,
    { players: players.map(id => ({ id: createPlayerId(id) })), seed: 'project-injected', matchID: identity('match', 0), gameID: identity('game', 0), cardCatalog: createRecordCardCatalog('synthetic-rule-03', definitions), cardsMaps: { owners, cardInstances }, capturePatches: false } as never);
  return {
    runtime,
    submit(actor: string, timestamp: number, commandId: string, move: string, input: Record<string, unknown>) {
      const args = move === 'chooseWhoGoesFirst' ? input : { ...input, playerId: actor };
      now = timestamp;
      const r = runtime.processCommand({ commandID: commandId, move, input: { args } } as never, actor, runtime.getCurrentStateID(), timestamp, 'player');
      return { accepted: r.success, code: r.success ? null : (r as { errorCode?: string }).errorCode ?? 'REJECTED' };
    },
  };
}
const kernel = (seed: Buffer, context: string, start: number, clock?: typeof NATIVE) =>
  createSyntheticKernel({ randomSource: createRandomSource(seed, context), players, startTimestamp: start, ...(clock ? { clock } : {}) });
const withoutTime = (state: any) => { const s = clone(state); delete s.ctx.time; delete s.ctx.rulesetHash; return s; };
function zones(state: any) { return state.ctx.zones.private.zoneCards; }

let lcg = 0x2026_1015;
const rand = (n: number) => { lcg = (Math.imul(lcg, 1103515245) + 12345) >>> 0; return (lcg >>> 16) % n; };
function pick<T>(a: T[]): T | undefined { return a.length ? a[rand(a.length)] : undefined; }
const GAPS = [0, 1, 250, 999, 4999, 5000, 59999, 60000, 124999, 125000, 125001, 149999, 150000, 150001, 210000];

const totals = { games: 0, commands: 0, accepted: 0, rejected: 0, fullStateEqualAfterAccept: 0, ctxTimeDivergenceOnReject: 0, convergedAfterReject: 0, untimedEqual: 0, eventsEqual: 0, movesEqual: 0, negativePasses: 0, timeoutCountMax: 0, passEndedGameByDeckOut: 0, exhaustedPassEndedGameByDeckOut: 0, endedReasons: {} as Record<string, number>, codes: {} as Record<string, number> };

function playGame(gameIndex: number) {
  const seed = randomBytes(32), context = 'audit-play04-parity-' + gameIndex, start = 1_000_000 + gameIndex;
  const T = kernel(seed, context, start, NATIVE), N = kernel(seed, context, start), R = rawRuntime(seed, context, start, NATIVE);
  assert.deepEqual(T.snapshot(), clone(R.runtime.getState()), 'initial timed bridge/raw state');
  assert.deepEqual(withoutTime(T.snapshot()), withoutTime(N.snapshot()), 'initial timed/untimed rules state');
  let ts = start, n = 0, pendingDivergence = false;
  const submitAll = (actor: string, move: string, input: Record<string, unknown>) => {
    ts += pick(GAPS)!;
    const id = 'g' + gameIndex + '-c' + n++;
    const before = T.clock();
    const t = T.submit(actor, T.status().revision, ts, id, move, clone(input));
    const u = N.submit(actor, N.status().revision, ts, id, move, clone(input));
    const r = R.submit(actor, ts, id, move, clone(input));
    totals.commands++;
    assert.equal(t.accepted, u.accepted, 'timed/untimed acceptance differs for ' + move);
    assert.equal(t.accepted, r.accepted, 'bridge/raw acceptance differs for ' + move);
    if (!t.accepted) { assert.equal(t.code, u.code); assert.equal(t.code, r.code, 'rejection code'); totals.codes[t.code!] = (totals.codes[t.code!] ?? 0) + 1; }
    const ts_ = T.snapshot(), rs = clone(R.runtime.getState()), us = N.snapshot();
    assert.deepEqual(withoutTime(ts_), withoutTime(us), 'rules state differs timed vs untimed after ' + move); totals.untimedEqual++;
    assert.deepEqual(withoutTime(ts_), withoutTime(rs), 'rules state differs bridge vs raw after ' + move);
    const te = T.inspect().events, ue = N.inspect().events, re = clone(R.runtime.getPublishedGameEvents());
    assert.deepEqual(te, re, 'published events differ bridge vs raw'); assert.deepEqual(te, ue, 'published events differ timed vs untimed'); totals.eventsEqual++;
    for (const p of players) { assert.deepEqual(T.inspect(p).moves, N.inspect(p).moves, 'legal moves differ timed/untimed'); totals.movesEqual++; }
    if (t.accepted) {
      totals.accepted++;
      assert.deepEqual(ts_, rs, 'full timed state differs bridge vs raw after accepted ' + move); totals.fullStateEqualAfterAccept++;
      if (pendingDivergence) { totals.convergedAfterReject++; pendingDivergence = false; }
      // Native arithmetic check for an outgoing exhausted player (decision-maker hand-off after natural pass).
      const after = T.clock()!;
      if (move === 'passTurn' && before && before.activePlayerId === actor) {
        const prior = before.players.find((p: any) => p.playerId === actor)!.remainingMs;
        const charged = ts - before.startedAtMs!;
        const now = after.players.find((p: any) => p.playerId === actor)!;
        if (after.activePlayerId === actor) {
          // Only a natural game end keeps the passer on the clock: CR 3.4.2 deck-out at end of turn (or a concession).
          const st: any = T.snapshot(); assert.equal(T.status().ended, true, 'pass kept active player without game end');
          assert.match(String(st.ctx.status.reason), new RegExp('^' + actor + ' ended their turn with no cards in their deck$'), 'unexpected same-player end');
          totals.passEndedGameByDeckOut++; if (prior - charged <= 0) totals.exhaustedPassEndedGameByDeckOut++;
        }
        else if (prior - charged <= 0) {
          totals.negativePasses++;
          assert.equal(now.remainingMs, Math.min(NATIVE.reserveCapMs, NATIVE.resetTimeOnSkipMs + NATIVE.perActionBonusMs + NATIVE.perTurnPassBonusMs), 'exhausted pass arithmetic');
        } else assert.equal(now.remainingMs, Math.min(NATIVE.reserveCapMs, prior - charged + NATIVE.perActionBonusMs + NATIVE.perTurnPassBonusMs), 'ordinary pass arithmetic');
        totals.timeoutCountMax = Math.max(totals.timeoutCountMax, now.timeoutCount);
      }
    } else {
      totals.rejected++;
      // Bridge prevalidates; raw upstream settles the clock before validating. Rules state must match; only ctx.time may differ.
      assert.deepEqual(T.clock(), before, 'bridge rejected move changed clock');
      if (JSON.stringify(ts_.ctx.time) !== JSON.stringify(rs.ctx.time)) { totals.ctxTimeDivergenceOnReject++; pendingDivergence = true; }
    }
    return t.accepted;
  };
  let guard = 0;
  while (!T.status().ended && guard++ < 3000) {
    const s: any = T.snapshot(), status = s.ctx.status;
    const actor = s.ctx.priority.pendingChoice?.playerID ?? s.ctx.priority.holder ?? players[0];
    const z = zones(s);
    // Deliberate invalid attempts interleaved (wrong player, bogus ids, opponent cards).
    if (rand(5) === 0) {
      const bad = [
        () => submitAll(other(actor), 'passTurn', {}),
        () => submitAll(actor, 'quest', { cardId: 'instance-' + 'f'.repeat(64) }),
        () => submitAll(actor, 'playCard', { cardId: pick(z['hand:' + other(actor)] ?? []) ?? 'x', cost: 'standard' }),
        () => submitAll(other(actor), 'putCardIntoInkwell', { cardId: pick(z['hand:' + other(actor)] ?? []) ?? 'x' }),
      ];
      pick(bad)!();
      continue;
    }
    if (status.choosingFirstPlayer && T.inspect(actor).moves.includes('chooseWhoGoesFirst')) { submitAll(actor, 'chooseWhoGoesFirst', { playerId: pick(players)! }); continue; }
    const mull = players.find(p => T.inspect(p).moves.includes('alterHand'));
    if (mull) { const hand = [...(z['hand:' + mull] ?? [])]; submitAll(mull, 'alterHand', { cardsToMulligan: hand.filter(() => rand(3) === 0) }); continue; }
    const options: (() => boolean)[] = [];
    for (const c of z['hand:' + actor] ?? []) { options.push(() => submitAll(actor, 'putCardIntoInkwell', { cardId: c })); options.push(() => submitAll(actor, 'playCard', { cardId: c, cost: 'standard' })); }
    for (const c of z['play:' + actor] ?? []) { options.push(() => submitAll(actor, 'quest', { cardId: c })); for (const d of z['play:' + other(actor)] ?? []) options.push(() => submitAll(actor, 'challenge', { attackerId: c, defenderId: d })); }
    options.push(() => submitAll(actor, 'passTurn', {}));
    if (rand(40) === 0) options.push(() => submitAll(actor, 'concede', {}));
    pick(options)!();
  }
  if (!T.status().ended) { const s: any = T.snapshot(); console.log(JSON.stringify({codes: totals.codes, accepted: totals.accepted, rejected: totals.rejected, time: s.ctx.time, turn: s.ctx.status.turn, phase: s.ctx.status.phase, seg: s.ctx.status.gameSegment, holder: s.ctx.priority.holder, lore: s.G.lore ?? null, deck: players.map(p => zones(s)['deck:' + p].length), hand: players.map(p => zones(s)['hand:' + p].length), play: players.map(p => zones(s)['play:' + p].length), moves: players.map(p => T.inspect(p).moves)})); }
  assert.ok(T.status().ended, 'game did not finish');
  assert.equal(N.status().ended, true); assert.equal(R.runtime.hasGameEnded(), true);
  assert.deepEqual(T.status(), N.status(), 'final status timed/untimed');
  const reason = (T.snapshot() as any).ctx.status.reason ?? 'none';
  totals.endedReasons[reason] = (totals.endedReasons[reason] ?? 0) + 1;
  assert.equal(T.clock()!.running, false, 'ended clock still running');
  totals.games++;
}
for (let g = 0; g < 24; g++) playGame(g);

// ---------- C: explicit boundaries, opening/choice behaviour and controls ----------
function opened(clock = NATIVE) {
  const k = kernel(randomBytes(32), 'audit-play04-boundary', 1000, clock);
  const s = k.status();
  assert.equal(k.submit(s.choosingFirstPlayer!, s.revision, 1000, 'o1', 'chooseWhoGoesFirst', { playerId: 'p1' }).accepted, true);
  for (const p of players) assert.equal(k.submit(p, k.status().revision, 1000, 'm' + p, 'alterHand', { cardsToMulligan: [] }).accepted, true);
  return k;
}
const rem = (k: any, p: string) => k.clock().players.find((x: any) => x.playerId === p).remainingMs;
const C: Record<string, unknown> = {};
{ // one millisecond before exhaustion: ordinary pass, no reset, timeout count unchanged
  const k = opened(); assert.equal(k.clock().activePlayerId, 'p1');
  assert.equal(k.submit('p1', k.status().revision, 1000 + 149999, 'x', 'passTurn', {}).accepted, true);
  assert.equal(rem(k, 'p1'), 1 + 5000 + 60000); assert.equal(k.clock().players[0].timeoutCount, 0); C.oneMsBefore = rem(k, 'p1');
}
{ // exactly at zero: native treats <=0 as exhausted -> reset 60000 + action 5000 + pass 60000
  const k = opened();
  assert.equal(k.submit('p1', k.status().revision, 1000 + 150000, 'x', 'passTurn', {}).accepted, true);
  assert.equal(rem(k, 'p1'), 125000); assert.equal(k.clock().players[0].timeoutCount, 1); C.exactZero = rem(k, 'p1');
}
{ // far past zero gives the same native replenishment (lateness cannot change the outcome)
  const k = opened();
  assert.equal(k.submit('p1', k.status().revision, 1000 + 999999, 'x', 'passTurn', {}).accepted, true);
  assert.equal(rem(k, 'p1'), 125000); C.farPast = rem(k, 'p1');
  // opponent not charged for the time before the hand-off
  assert.equal(rem(k, 'p2'), 150000);
}
{ // a non-pass action by an exhausted player keeps them active and negative (no reset until hand-off)
  const k = opened(); const hand = zones(k.snapshot())['hand:p1'];
  assert.equal(k.submit('p1', k.status().revision, 1000 + 160000, 'x', 'putCardIntoInkwell', { cardId: hand[0] }).accepted, true);
  assert.equal(rem(k, 'p1'), -10000 + 5000); assert.equal(k.clock().activePlayerId, 'p1'); C.negativeAction = rem(k, 'p1');
}
{ // opening: chooser is on the clock; passTurn is not legal during choosing or mulligan (flow-disallowed)
  const k = kernel(randomBytes(32), 'audit-play04-opening', 1000, NATIVE); const chooser = k.status().choosingFirstPlayer!;
  assert.equal(k.clock().activePlayerId, chooser); assert.equal(k.clock().running, true);
  const r1 = k.submit(chooser, k.status().revision, 2000, 'p', 'passTurn', {}); assert.equal(r1.accepted, false); C.choosingPassCode = r1.code;
  assert.equal(k.submit(chooser, k.status().revision, 3000, 'c', 'chooseWhoGoesFirst', { playerId: other(chooser) }).accepted, true);
  const mulliganer = k.clock().activePlayerId; C.firstMulliganer = mulliganer === other(chooser) ? 'chosen-first-player' : 'chooser';
  const r2 = k.submit(mulliganer, k.status().revision, 4000, 'p2', 'passTurn', {}); assert.equal(r2.accepted, false); C.mulliganPassCode = r2.code;
  assert.equal(rem(k, chooser), Math.min(150000, 150000 - 2000 + 5000), 'chooser charged only for own decision time then capped action bonus');
}
{ // controls: pause excludes interval, preserves state id/events/G; paused clock refuses valid moves in the bridge only
  const k = opened(); const g0 = withoutTime(k.snapshot()), e0 = k.inspect().events, id0 = k.status().revision;
  k.controlClock({ kind: 'pause', timestamp: 11000, reason: 'SERVER_RECOVERY' });
  assert.equal(rem(k, 'p1'), 140000); assert.deepEqual(withoutTime(k.snapshot()), g0); assert.deepEqual(k.inspect().events, e0); assert.equal(k.status().revision, id0);
  const refused = k.submit('p1', id0, 12000, 'pp', 'passTurn', {}); assert.deepEqual(refused, { accepted: false, code: 'CLOCK_PAUSED' });
  assert.throws(() => k.controlClock({ kind: 'settle', timestamp: 10999 }), 'backward control');
  k.controlClock({ kind: 'resume', timestamp: 500000 }); assert.equal(rem(k, 'p1'), 140000);
  assert.equal(k.submit('p1', id0, 501000, 'pp2', 'passTurn', {}).accepted, true); assert.equal(rem(k, 'p1'), 150000, 'capped');
  C.pauseExcluded = true;
  // Raw upstream would accept a move while paused and silently restart the clock (step 8). Document the divergence.
  const R = rawRuntime(randomBytes(32), 'audit-raw-paused', 1000, NATIVE); const s0: any = R.runtime.getState();
  R.submit(s0.ctx.status.choosingFirstPlayer, 1000, 'a', 'chooseWhoGoesFirst', { playerId: 'p1' });
  for (const p of players) R.submit(p, 1000, 'm' + p, 'alterHand', { cardsToMulligan: [] });
  const { pauseClock } = await import(U + 'core/runtime/time-control.ts');
  R.runtime.restoreState(pauseClock(R.runtime.getState(), 'SERVER_RECOVERY', 2000), R.runtime.createRuntimeSnapshot(), { preserveHistory: true });
  const rawPaused = R.submit('p1', 3000, 'b', 'passTurn', {}); C.rawUpstreamAcceptsMoveWhilePaused = rawPaused.accepted; C.rawUpstreamClockRestarted = (R.runtime.getState() as any).ctx.time.running;
}
{ // reset requires paused clock, bounded by cap, does not increment timeout count, clears negative flag
  const k = opened(); k.controlClock({ kind: 'pause', timestamp: 200000, reason: 'SERVER_RECOVERY' });
  assert.equal(rem(k, 'p1'), 150000 - 199000);
  k.controlClock({ kind: 'reset', timestamp: 200000, playerId: 'p1', remainingMs: 30000 });
  assert.equal(rem(k, 'p1'), 30000); assert.equal(k.clock().players[0].timeoutCount, 0);
  k.controlClock({ kind: 'resume', timestamp: 200000 });
  assert.equal(k.submit('p1', k.status().revision, 201000, 'q', 'passTurn', {}).accepted, true);
  assert.equal(rem(k, 'p1'), 30000 - 1000 + 65000, 'reset cleared exhaustion so pass is ordinary'); C.resetThenPass = rem(k, 'p1');
}
console.log(JSON.stringify({ totals, boundaries: C }));
